In code, this can be accomplished by the following:
  // Mark Documents folder with special attribute to tell iOS not to back up to iCloud.
  const char* cstr = [documentsDirectory UTF8String] ;
  const char* attrName = "com.apple.MobileBackup";
  u_int8_t attrValue = 1;
  int result = setxattr(cstr, attrName, &attrValue, sizeof(attrValue), 0, 0); // 0 is success, -1 is failure

  if(result != 0){
  NSLog(@"Error: Documents folder could not be set to not backup to iCloud");
  }

